import fs from 'node:fs'

const lv = JSON.parse(fs.readFileSync('electron/playerLevels.fallback.json', 'utf8'))
const body = lv.map((x) => `  { level: ${x.level}, exp: ${x.exp} },`).join('\n')
const source = `/** The game's experience table (incremental: \`exp\` is what a level takes after the one before), for when Tarkov.dev's is
 * not at hand: the main process (electron/playerLevels.fallback.ts) and the quest experience (src/profile/questExperience.ts).
 * Generated by scripts/gen-player-levels.mjs. */
import type { PlayerLevelRow } from './playerProfileNormalizer.js'

export const PLAYER_LEVELS: PlayerLevelRow[] = [
${body}
]
`
fs.writeFileSync('src/profile/playerLevels.ts', source)
console.log('wrote', lv.length)
